<?php
declare(strict_types=1);

const APP_NAME = 'Central Authentication Gateway';
const APP_SHORT = 'CAG';
const APP_VERSION = '1.0.0';
const STORAGE = __DIR__ . '/storage';
const DB_FILE = STORAGE . '/auth.sqlite';
const KEY_DIR = STORAGE . '/keys';
const ICON_DIR = STORAGE . '/icons';
const MAX_ICON = 2097152;
const TOKEN_LIFETIME = 36000;

ini_set('display_errors', '0');
ini_set('log_errors', '1');
error_reporting(E_ALL);
date_default_timezone_set('UTC');

$secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
session_name('cag_session');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Lax']);
session_start();
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: no-referrer');
header('Permissions-Policy: camera=(), microphone=(), geolocation=()');
header("Content-Security-Policy: default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");

function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function now(): int { return time(); }
function id(string $prefix='id'): string { return $prefix . '_' . bin2hex(random_bytes(12)); }
function b64u(string $value): string { return rtrim(strtr(base64_encode($value), '+/', '-_'), '='); }
function b64ud(string $value): string { $p = strlen($value) % 4; if ($p) $value .= str_repeat('=', 4-$p); return (string)base64_decode(strtr($value, '-_', '+/'), true); }
function app_url(): string {
    $scheme = ((!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https')) ? 'https' : 'http';
    $host = preg_replace('/[^A-Za-z0-9.\-:\[\]]/', '', $_SERVER['HTTP_HOST'] ?? 'localhost');
    $path = str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/'));
    return $scheme . '://' . $host . ($path === '/' ? '' : rtrim($path, '/')) . '/';
}
function ensure_dir(string $path): void { if (!is_dir($path) && !mkdir($path, 0750, true) && !is_dir($path)) throw new RuntimeException('Verzeichnis konnte nicht angelegt werden: ' . $path); }
function db(): PDO {
    static $db;
    if ($db instanceof PDO) return $db;
    ensure_dir(STORAGE); ensure_dir(KEY_DIR); ensure_dir(ICON_DIR);
    $db = new PDO('sqlite:' . DB_FILE, null, null, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
    $db->exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000');
    return $db;
}
function schema(): void {
    db()->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (
 id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', password_hash TEXT,
 internal_role TEXT NOT NULL DEFAULT 'user' CHECK(internal_role IN ('user','admin')), must_change_password INTEGER NOT NULL DEFAULT 0,
 mfa_required INTEGER NOT NULL DEFAULT 0, totp_secret TEXT, totp_enabled INTEGER NOT NULL DEFAULT 0, last_totp_counter INTEGER,
 source TEXT NOT NULL DEFAULT 'local', ldap_dn TEXT, icon TEXT, active INTEGER NOT NULL DEFAULT 1, failed_logins INTEGER NOT NULL DEFAULT 0,
 locked_until INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS groups (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, description TEXT NOT NULL DEFAULT '', icon TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, description TEXT NOT NULL DEFAULT '', icon TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, description TEXT NOT NULL DEFAULT '', icon TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS systems (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, target_url TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', icon TEXT, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_groups (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, PRIMARY KEY(user_id,group_id));
CREATE TABLE IF NOT EXISTS assignments (
 id TEXT PRIMARY KEY, subject_type TEXT NOT NULL CHECK(subject_type IN ('user','group')), subject_id TEXT NOT NULL,
 system_id TEXT NOT NULL REFERENCES systems(id) ON DELETE CASCADE, role_id TEXT REFERENCES roles(id) ON DELETE CASCADE,
 tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, created_at INTEGER NOT NULL,
 UNIQUE(subject_type,subject_id,system_id,role_id,tenant_id)
);
CREATE TABLE IF NOT EXISTS ldap_sources (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, uri TEXT NOT NULL, base_dn TEXT NOT NULL, bind_dn TEXT NOT NULL DEFAULT '', bind_password_enc TEXT NOT NULL DEFAULT '',
 user_filter TEXT NOT NULL DEFAULT '(sAMAccountName={username})', start_tls INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, ip TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, first_at INTEGER NOT NULL, blocked_until INTEGER);
CREATE TABLE IF NOT EXISTS token_keys (kid TEXT PRIMARY KEY, public_key TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_token_keys_expiry ON token_keys(expires_at);
CREATE INDEX IF NOT EXISTS idx_assign_system ON assignments(system_id);
CREATE INDEX IF NOT EXISTS idx_assign_subject ON assignments(subject_type,subject_id);
SQL);
}
function setting(string $key, ?string $default=null): ?string { $s=db()->prepare('SELECT value FROM settings WHERE key=?'); $s->execute([$key]); $r=$s->fetchColumn(); return $r===false?$default:(string)$r; }
function set_setting(string $key, string $value): void { $s=db()->prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value'); $s->execute([$key,$value]); }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if (!hash_equals($_SESSION['csrf'] ?? '', (string)($_POST['csrf'] ?? ''))) throw new RuntimeException('Ungültige Sitzung. Seite neu laden.'); }
function flash(string $type,string $message): void { $_SESSION['flash'][]=['type'=>$type,'message'=>$message]; }
function redirect(string $url): never { header('Location: '.$url, true, 303); exit; }
function audit(string $action,string $type='',string $oid='',array $details=[]): void { $s=db()->prepare('INSERT INTO audit_events(created_at,actor,action,object_type,object_id,ip,details) VALUES(?,?,?,?,?,?,?)'); $s->execute([now(),$_SESSION['uid']??'system',$action,$type,$oid,$_SERVER['REMOTE_ADDR']??'',json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]); }
function one(string $sql,array $p=[]): ?array { $s=db()->prepare($sql); $s->execute($p); $r=$s->fetch(); return $r?:null; }
function all(string $sql,array $p=[]): array { $s=db()->prepare($sql); $s->execute($p); return $s->fetchAll(); }
function current_user(): ?array { if (empty($_SESSION['uid'])) return null; return one('SELECT * FROM users WHERE id=? AND active=1',[$_SESSION['uid']]); }
function login_required(): array { $u=current_user(); if(!$u){ $_SESSION['after_login']=$_SERVER['REQUEST_URI']??'?'; redirect('?'); } return $u; }
function admin_required(): array { $u=login_required(); if($u['internal_role']!=='admin') throw new RuntimeException('Administratorrechte erforderlich.'); return $u; }
function admin_count(): int { return (int)db()->query("SELECT COUNT(*) FROM users WHERE internal_role='admin' AND active=1")->fetchColumn(); }
function password_hash_safe(string $password): string { return password_hash($password, defined('PASSWORD_ARGON2ID') ? PASSWORD_ARGON2ID : PASSWORD_DEFAULT); }
function valid_password(string $p): bool { return strlen($p)>=12 && preg_match('/[A-ZÄÖÜ]/u',$p) && preg_match('/[a-zäöüß]/u',$p) && preg_match('/\d/',$p); }
function base32_decode_safe(string $secret): string {
    $alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'; $secret=strtoupper(preg_replace('/[^A-Z2-7]/','',$secret)); $bits=''; $out='';
    foreach(str_split($secret) as $c){$v=strpos($alphabet,$c); if($v===false) continue; $bits.=str_pad(decbin($v),5,'0',STR_PAD_LEFT);}
    foreach(str_split($bits,8) as $b) if(strlen($b)===8) $out.=chr(bindec($b)); return $out;
}
function base32_encode_safe(string $raw): string { $a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';$o='';foreach(str_split($raw) as $c)$bits.=str_pad(decbin(ord($c)),8,'0',STR_PAD_LEFT);foreach(str_split($bits,5) as $b){if(strlen($b)<5)$b=str_pad($b,5,'0');$o.=$a[bindec($b)];}return $o; }
function totp_code(string $secret,int $counter): string { $key=base32_decode_safe($secret);$bin=pack('N*',0).pack('N*',$counter);$h=hash_hmac('sha1',$bin,$key,true);$o=ord($h[19])&15;$n=((ord($h[$o])&127)<<24)|((ord($h[$o+1])&255)<<16)|((ord($h[$o+2])&255)<<8)|(ord($h[$o+3])&255);return str_pad((string)($n%1000000),6,'0',STR_PAD_LEFT); }
function verify_totp(array $u,string $code): bool { if(!preg_match('/^\d{6}$/',$code) || !$u['totp_secret']) return false; $c=intdiv(time(),30); foreach([-1,0,1] as $w){$x=$c+$w;if(totp_code($u['totp_secret'],$x)===$code && ($u['last_totp_counter']===null || $x>(int)$u['last_totp_counter'])){db()->prepare('UPDATE users SET last_totp_counter=? WHERE id=?')->execute([$x,$u['id']]);return true;}}return false; }
function cleanup_token_keys(): void { db()->prepare('DELETE FROM token_keys WHERE expires_at<=?')->execute([now()]); }
function create_token_key(): array {
    cleanup_token_keys();
