    $details=openssl_pkey_get_details($res);if(!$details||empty($details['key']))throw new RuntimeException('Öffentlicher Token-Schlüssel konnte nicht erzeugt werden.');
    db()->prepare('INSERT INTO token_keys(kid,public_key,created_at,expires_at) VALUES(?,?,?,?)')->execute([$kid,$details['key'],$created,$expires]);
    return ['kid'=>$kid,'private'=>$private,'public'=>$details['key'],'created_at'=>$created,'expires_at'=>$expires];
}
function jwt(array $claims): string {
    $key=create_token_key();
