    $a=b64u(json_encode($head,JSON_UNESCAPED_SLASHES));$b=b64u(json_encode($claims,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));
    $private=openssl_pkey_get_private($key['private']);
    if(!$private||!openssl_sign($a.'.'.$b,$sig,$private,OPENSSL_ALGO_SHA256))throw new RuntimeException('Token konnte nicht signiert werden.');
    unset($key['private']);
    return $a.'.'.$b.'.'.b64u($sig);
}
function jwk_from_pem(string $pem,string $kid): array { $k=openssl_pkey_get_public($pem);$d=$k?openssl_pkey_get_details($k):false;if(!$d||empty($d['rsa']))throw new RuntimeException('Öffentlicher Schlüssel ungültig.');return ['kty'=>'RSA','use'=>'sig','alg'=>'RS256','kid'=>$kid,'n'=>b64u($d['rsa']['n']),'e'=>b64u($d['rsa']['e'])]; }
function system_claims(string $uid,string $sid): array {
    $groups=all('SELECT g.id,g.name FROM groups g JOIN user_groups ug ON ug.group_id=g.id WHERE ug.user_id=?',[$uid]);$gids=array_column($groups,'id');$params=[$sid,$uid];$where="a.system_id=? AND ((a.subject_type='user' AND a.subject_id=?)";
    if($gids){$where.=" OR (a.subject_type='group' AND a.subject_id IN (".implode(',',array_fill(0,count($gids),'?')).'))';$params=array_merge($params,$gids);}else{$where.=')';}
    $rows=all("SELECT DISTINCT r.name role,t.name tenant FROM assignments a LEFT JOIN roles r ON r.id=a.role_id LEFT JOIN tenants t ON t.id=a.tenant_id WHERE $where",$params);
    return ['groups'=>array_values(array_unique(array_column($groups,'name'))),'roles'=>array_values(array_unique(array_filter(array_column($rows,'role')))),'tenants'=>array_values(array_unique(array_filter(array_column($rows,'tenant'))))];
}
function can_access_system(string $uid,string $sid): bool { $c=system_claims($uid,$sid);if($c['roles']||$c['groups']||$c['tenants'])return true;$s=db()->prepare("SELECT COUNT(*) FROM assignments WHERE system_id=? AND subject_type='user' AND subject_id=?");$s->execute([$sid,$uid]);return (int)$s->fetchColumn()>0; }
function icon_path(string $kind,string $name): ?string { if(!preg_match('/^(users|groups|roles|tenants|systems)$/',$kind)||!preg_match('/^[a-zA-Z0-9._-]+$/',$name))return null;$p=ICON_DIR.'/'.$kind.'/'.$name;return is_file($p)?$p:null; }
function save_icon(string $kind,string $objectId,string $fieldTable): ?string {
    if(empty($_FILES['icon']['tmp_name'])||($_FILES['icon']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;
    if($_FILES['icon']['error']!==UPLOAD_ERR_OK||$_FILES['icon']['size']>MAX_ICON)throw new RuntimeException('Icon-Upload fehlgeschlagen oder größer als 2 MB.');
