<?php elseif($view==='assignments'):$users=all('SELECT id,username name FROM users WHERE active=1 ORDER BY username');$groups=all('SELECT id,name FROM groups ORDER BY name');$systems=all('SELECT id,name FROM systems ORDER BY name');$roles=all('SELECT id,name FROM roles ORDER BY name');$tenants=all('SELECT id,name FROM tenants ORDER BY name');$rows=all("SELECT a.*,s.name system_name,r.name role_name,t.name tenant_name,CASE WHEN a.subject_type='user' THEN u.username ELSE g.name END subject_name FROM assignments a JOIN systems s ON s.id=a.system_id LEFT JOIN roles r ON r.id=a.role_id LEFT JOIN tenants t ON t.id=a.tenant_id LEFT JOIN users u ON a.subject_type='user' AND u.id=a.subject_id LEFT JOIN groups g ON a.subject_type='group' AND g.id=a.subject_id ORDER BY s.name,subject_name");?><section class="card"><h2>Zuweisung anlegen</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assignment_save"><label>Subjekttyp<select name="subject_type" id="subject-type" onchange="subjectOptions()"><option value="user">Benutzer</option><option value="group">Gruppe</option></select></label><label>Subjekt<select name="subject_id" id="subject-id"></select></label><label>System<select name="system_id"><?php foreach($systems as $x):?><option value="<?=e($x['id'])?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Rolle<select name="role_id"><option value="">Keine</option><?php foreach($roles as $x):?><option value="<?=e($x['id'])?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Tenant<select name="tenant_id"><option value="">Keiner</option><?php foreach($tenants as $x):?><option value="<?=e($x['id'])?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><div class="actions full"><button class="primary">Anlegen</button></div></form></section><table><thead><tr><th>Subjekt</th><th>System</th><th>Rolle</th><th>Tenant</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['subject_type'].' · '.$r['subject_name'])?></td><td><?=e($r['system_name'])?></td><td><?=e($r['role_name']??'')?></td><td><?=e($r['tenant_name']??'')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assignment_delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="danger">Löschen</button></form></td></tr><?php endforeach;?></tbody></table><script>const subjects={user:<?=json_encode($users)?>,group:<?=json_encode($groups)?>};function subjectOptions(){const t=document.getElementById('subject-type').value;document.getElementById('subject-id').innerHTML=subjects[t].map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}subjectOptions()</script>
<?php elseif($view==='audit'):$rows=all('SELECT * FROM audit_events ORDER BY id DESC LIMIT 500');?><table><thead><tr><th>Zeit</th><th>Akteur</th><th>Aktion</th><th>Objekt</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('Y-m-d H:i:s',$r['created_at']))?></td><td><?=e($r['actor'])?></td><td><?=e($r['action'])?></td><td><?=e($r['object_type'].' '.$r['object_id'])?></td><td><?=e($r['ip'])?></td></tr><?php endforeach;?></tbody></table>
<?php elseif($view==='settings'):?><section class="card"><h2>JWT und Token-Schlüssel</h2><p>Token-Lebensdauer: <strong>10 Stunden</strong></p><p>Issuer: <span class="code"><?=e(rtrim(setting('base_url',app_url()),'/'))?></span></p><p>JWKS aller noch gültigen Token-Schlüssel: <span class="code"><?=e(setting('base_url',app_url()).'?jwks=1')?></span></p><p>Einzelschlüssel: <span class="code"><?=e(setting('base_url',app_url()).'?public_key=&lt;kid&gt;')?></span></p><p class="muted">Für jedes Token wird ein eigenes RSA-Schlüsselpaar erzeugt. Nur der öffentliche Schlüssel wird bis zum Ablauf gespeichert und bereitgestellt. Der private Schlüssel wird nach dem Signieren nicht persistiert.</p></section><section class="card"><h2>LDAP und Active Directory</h2><p class="muted">Die Datenbankstruktur für LDAP-Quellen ist vorbereitet. Produktiv sollte die Verzeichnisanbindung mit LDAPS oder StartTLS, einem lesenden Servicekonto und einer expliziten Gruppenabbildung konfiguriert werden. Lokale Administratoren bleiben als Notfallzugang erhalten.</p></section><?php endif;?></main></div>
<dialog id="user-dialog"><h2>Benutzer</h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="user_save"><input type="hidden" name="id"><label>Benutzername<input name="username" required></label><label>Anzeigename<input name="display_name"></label><label>E-Mail<input type="email" name="email"></label><label>Passwort<input type="password" name="password" placeholder="Leer = unverändert"></label><label>Interne Stufe<select name="internal_role"><option value="user">User</option><option value="admin">Admin</option></select></label><label>Icon<input type="file" name="icon" accept="image/png,image/jpeg"></label><label><input type="checkbox" name="active" value="1"> Aktiv</label><label><input type="checkbox" name="must_change_password" value="1"> Passwortwechsel bei erster Anmeldung</label><label><input type="checkbox" name="mfa_required" value="1"> TOTP verpflichtend</label><div class="actions full"><button type="button" onclick="this.closest('dialog').close()">Abbrechen</button><button class="primary">Speichern</button></div></form></dialog>
<dialog id="entity-dialog"><h2><?=e(in_array($view,['groups','roles','tenants','systems'],true)?entity($view)['title']:'Eintrag')?></h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="entity_save"><input type="hidden" name="type" value="<?=e($view)?>"><input type="hidden" name="id"><label>Name<input name="name" required></label><?php if($view==='systems'):?><label>Ziel-URL<input type="url" name="target_url" required></label><label><input type="checkbox" name="active" value="1"> Aktiv</label><?php endif;?><label class="full">Beschreibung<textarea name="description"></textarea></label><label>Icon<input type="file" name="icon" accept="image/png,image/jpeg"></label><div class="actions full"><button type="button" onclick="this.closest('dialog').close()">Abbrechen</button><button class="primary">Speichern</button></div></form></dialog>
<script>function openUser(r){const d=document.getElementById('user-dialog'),f=d.querySelector('form');f.reset();for(const k of ['id','username','display_name','email','internal_role'])if(f.elements[k])f.elements[k].value=r[k]??(k==='internal_role'?'user':'');for(const k of ['active','must_change_password','mfa_required'])f.elements[k].checked=k==='active'?(r[k]===undefined?true:!!Number(r[k])):!!Number(r[k]);d.showModal()}function openEntity(r){const d=document.getElementById('entity-dialog'),f=d.querySelector('form');f.reset();for(const k of ['id','name','description','target_url'])if(f.elements[k])f.elements[k].value=r[k]??'';if(f.elements.active)f.elements.active.checked=r.active===undefined?true:!!Number(r.active);d.showModal()}</script></body></html>
